package com.bank.notification;

import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.logging.*;

public class NotificationDemo {
    private static final Logger log = Logger.getLogger(NotificationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Register providers behind the interface. The dispatcher never
        // names Twilio/FCM/SendGrid directly — it only knows the channel.
        Map<NotificationChannel, NotificationProvider> providers = new EnumMap<>(NotificationChannel.class);
        providers.put(NotificationChannel.SMS, new FlakyTwilioSmsProvider());   // fails twice, then works
        providers.put(NotificationChannel.PUSH, new HealthyFcmProvider());
        providers.put(NotificationChannel.EMAIL, new HealthySendGridProvider());

        RetryPolicy retry = new RetryPolicy(4, 1000, 30000, 500);
        DeadLetterQueue dlq = new DeadLetterQueue();
        NotificationDispatcher dispatcher =
                new NotificationDispatcher(providers, new ErrorClassifier(), retry, dlq);

        // Scenario 1: OTP to Rajesh via SMS — transient failure, recovers on retry
        dispatcher.dispatch(new Notification(
                "NTF-1", NotificationChannel.SMS, "+919812345678",
                "OTP for SAV2001 login is 482913", "SAV2001"));

        // Scenario 2: alert to Priya via SMS — permanent failure (bad number)
        dispatcher.dispatch(new Notification(
                "NTF-2", NotificationChannel.SMS, "INVALID_NUMBER",
                "Rs.25000 debited from CUR3001", "CUR3001"));

        log.info(() -> "DLQ size after run = " + dlq.size());
    }
}

// ─── Would be in model/NotificationChannel.java ───
enum NotificationChannel { SMS, PUSH, EMAIL }

// ─── Would be in model/FailureType.java ───
enum FailureType { NONE, RETRYABLE, NON_RETRYABLE }

// ─── Would be in model/Notification.java ───
class Notification {
    final String id;
    final NotificationChannel channel;
    final String target;      // phone / token / email
    final String body;
    final String accountId;
    Notification(String id, NotificationChannel channel, String target, String body, String accountId) {
        this.id = id; this.channel = channel; this.target = target;
        this.body = body; this.accountId = accountId;
    }
}

// ─── Would be in model/DeliveryResult.java ───
class DeliveryResult {
    final boolean success;
    final int httpStatus;     // provider HTTP code (0 if network error)
    final String message;
    private DeliveryResult(boolean s, int code, String m) { success = s; httpStatus = code; message = m; }
    static DeliveryResult ok() { return new DeliveryResult(true, 200, "delivered"); }
    static DeliveryResult fail(int code, String m) { return new DeliveryResult(false, code, m); }
}

// ─── Would be in provider/NotificationProvider.java ───
interface NotificationProvider {
    DeliveryResult send(Notification n);
    NotificationChannel channel();
}

// ─── Would be in provider/TwilioSmsProvider.java ───
// Flaky vendor: first two SMS attempts time out (HTTP 503), then succeeds.
// A bad target returns HTTP 400 (permanent).
class FlakyTwilioSmsProvider implements NotificationProvider {
    private int attempts = 0;
    public NotificationChannel channel() { return NotificationChannel.SMS; }
    public DeliveryResult send(Notification n) {
        if ("INVALID_NUMBER".equals(n.target)) {
            return DeliveryResult.fail(400, "invalid MSISDN — cannot deliver");
        }
        attempts++;
        if (attempts <= 2) return DeliveryResult.fail(503, "provider temporarily unavailable");
        return DeliveryResult.ok();
    }
}

// ─── Would be in provider/FcmPushProvider.java ───
class HealthyFcmProvider implements NotificationProvider {
    public NotificationChannel channel() { return NotificationChannel.PUSH; }
    public DeliveryResult send(Notification n) { return DeliveryResult.ok(); }
}

// ─── Would be in provider/SendGridEmailProvider.java ───
class HealthySendGridProvider implements NotificationProvider {
    public NotificationChannel channel() { return NotificationChannel.EMAIL; }
    public DeliveryResult send(Notification n) { return DeliveryResult.ok(); }
}

// ─── Would be in retry/ErrorClassifier.java ───
// Decides whether a failure is permanent or transient.
class ErrorClassifier {
    FailureType classify(DeliveryResult r) {
        if (r.success) return FailureType.NONE;
        int code = r.httpStatus;
        // 4xx (except 429) = client error = permanent. 429/5xx/0 = transient.
        if (code == 429 || code >= 500 || code == 0) return FailureType.RETRYABLE;
        return FailureType.NON_RETRYABLE;
    }
}

// ─── Would be in retry/RetryPolicy.java ───
// Exponential backoff with jitter so retries do not land together.
class RetryPolicy {
    final int maxAttempts; final long baseMs; final long capMs; final long jitterMs;
    RetryPolicy(int maxAttempts, long baseMs, long capMs, long jitterMs) {
        this.maxAttempts = maxAttempts; this.baseMs = baseMs; this.capMs = capMs; this.jitterMs = jitterMs;
    }
    long delayForAttempt(int attempt) {
        long exp = Math.min(capMs, baseMs * (1L << Math.min(attempt, 20)));
        long jitter = ThreadLocalRandom.current().nextLong(0, jitterMs + 1);
        return exp + jitter;
    }
}

// ─── Would be in dlq/DeadLetterQueue.java ───
class DeadLetterQueue {
    private final List<String> dead = new ArrayList<>();
    void park(Notification n, String reason) { dead.add(n.id + " : " + reason); }
    int size() { return dead.size(); }
}

// ─── Would be in dispatch/NotificationDispatcher.java ───
class NotificationDispatcher {
    private static final Logger log = Logger.getLogger(NotificationDispatcher.class.getName());
    private final Map<NotificationChannel, NotificationProvider> providers;
    private final ErrorClassifier classifier;
    private final RetryPolicy retry;
    private final DeadLetterQueue dlq;

    NotificationDispatcher(Map<NotificationChannel, NotificationProvider> providers,
                           ErrorClassifier classifier, RetryPolicy retry, DeadLetterQueue dlq) {
        this.providers = providers; this.classifier = classifier; this.retry = retry; this.dlq = dlq;
    }

    void dispatch(Notification n) {
        NotificationProvider provider = providers.get(n.channel);
        for (int attempt = 0; attempt < retry.maxAttempts; attempt++) {
            DeliveryResult result = provider.send(n);
            if (result.success) {
                log.info(() -> "DELIVERED " + n.id + " to " + n.accountId + " via " + n.channel);
                return;
            }
            FailureType type = classifier.classify(result);
            if (type == FailureType.NON_RETRYABLE) {
                log.severe("PERMANENT FAILURE " + n.id + " (" + result.message + ") — marking FAILED, no retry");
                dlq.park(n, "permanent: " + result.message);
                return;
            }
            // retryable
            long delay = retry.delayForAttempt(attempt);
            log.warning("TRANSIENT FAILURE " + n.id + " (" + result.message
                    + ") attempt " + (attempt + 1) + " — backoff " + delay + "ms");
            sleep(delay);
        }
        log.severe("RETRIES EXHAUSTED " + n.id + " — sending to DLQ");
        dlq.park(n, "retries exhausted");
    }

    private void sleep(long ms) {
        try { Thread.sleep(Math.min(ms, 50)); } // shortened for demo speed
        catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
